    pgDo(i, a) { const e = (xb.__pg || [])[i]; if (!e) return; xb.pick(e); if (a === "sel") return; if (a === "hide") { const r = xb.rule(true); xb.setR("hide", !r.hide); } else xb.move(a); xb.tab = "pg"; setTimeout(() => xb.side(), 250); },
